+    Map<String, DatabaseReaderLazyLoader> initDefaultDatabases(Path geoipModuleDir) {
+        Map<String, DatabaseReaderLazyLoader> databases = new HashMap<>(DEFAULT_DATABASE_FILENAMES.length);
