+        return Collections.unmodifiableMap(databases);
+    }
+
+    Map<String, DatabaseReaderLazyLoader> initConfigDatabases(Path geoipConfigDir) throws IOException {
+        Map<String, DatabaseReaderLazyLoader> databases = new HashMap<>();
