+                        DatabaseReaderLazyLoader loader = new DatabaseReaderLazyLoader(cache, databasePath);
+                        databases.put(databaseFileName, loader);
+                    }
+                }
+            }
+        }
+
+        return Collections.unmodifiableMap(databases);
