+    public <T> Leak<T> track(T obj) {
+        reportLeak();
+        return new Leak<>(obj, refQueue, allLeaks);
+    }
+
+    public void reportLeak() {
+        while (true) {
+            Leak<?> ref = (Leak<?>) refQueue.poll();
+            if (ref == null) {
+                break;
+            }
