+            if (dropped > 0) {
+                buf.append(": ")
+                        .append(dropped)
+                        .append(" leak records were discarded because the leak record count is targeted to ")
+                        .append(TARGET_RECORDS)
+                        .append('.')
+                        .append('\n');
