+        }
+
+        @Override
+        public int read() {
+            if (current == null) {
+                if (data.hasNext() == false) {
+                    return -1;
+                }
+
+                current = new ByteArrayInputStream(data.next());
+            }
+            int read = current.read();
+            if (read == -1) {
+                current = null;
+                return read();
+            }
+            return read;
+        }
+
+        @Override
+        public int read(byte[] b, int off, int len) throws IOException {
